474: function statusLine(
475:   phase: Phase,
476:   samples: PulseSample[],
477:   note: string,
478:   validation: ValidationMessage | null,
479: ): string {
480:   if (phase !== 'sensing') return note;
481:   if (validation && validation.code !== 0) return validation.hint;
482:   if (samples.length === 0) return 'Waiting for a face.';
483:   const latest = samples[samples.length - 1];
484:   if (!latest.stable || latest.confidence < CONFIDENCE_FLOOR) {
485:     return samples.some((sample) => sample.stable && sample.confidence >= CONFIDENCE_FLOOR)
486:       ? 'Low confidence.'
487:       : 'Validating.';
488:   }
489:   return 'Sensing.';
490: }
