502: /** Electron wraps a rejected invoke in "Error invoking remote method …: Error: ", which is not for the player. */
503: function ipcErrorText(caught: unknown, fallback: string): string {
504:   if (!(caught instanceof Error)) return fallback;
505:   const marker = 'Error: ';
506:   const at = caught.message.lastIndexOf(marker);
507:   const text = (at >= 0 ? caught.message.slice(at + marker.length) : caught.message).trim();
