    elevatedThresholdBpm: report.timeline.elevatedThresholdBpm,
    settled: report.settled,
    elevated: report.elevated,
    alignmentMode: report.alignmentMode,
    toleranceSec: report.toleranceSec,
    games: report.games.map((game) => ({
