export function isAppErrorCode(value: unknown): value is AppErrorCode {
  return typeof value === 'string' && (APP_ERROR_CODES as readonly string[]).includes(value);
}

export function appErrorInfo(code: AppErrorCode): AppErrorInfo {
  return { code, ...APP_ERRORS[code] };
}

/** A failure that already carries a player-facing meaning. The message is never supplied ad hoc. */
export class AppError extends Error {
  readonly code: AppErrorCode;
  readonly retryable: boolean;

  constructor(code: AppErrorCode, options: { cause?: unknown } = {}) {
    super(
      APP_ERRORS[code].message,
      options.cause === undefined ? undefined : { cause: options.cause },
    );
    this.name = 'AppError';
    this.code = code;
    this.retryable = APP_ERRORS[code].retryable;
  }
}

export function isAppError(value: unknown): value is AppError {
  return value instanceof AppError;
}

/** Any throw becomes one typed error. An unknown failure keeps its detail as `cause`, never as copy. */
export function toAppError(value: unknown, fallback: AppErrorCode = 'internal'): AppError {
  return isAppError(value) ? value : new AppError(fallback, { cause: value });
}

const WIRE_PREFIX = 'chesspulse-error:';

/** The code, not the prose, is what crosses a process or context boundary. */
export function serializeAppError(error: AppError): string {
  return `${WIRE_PREFIX}${error.code}`;
}

/** Electron prefixes its own text, so the marker is found from the end of the message. */
export function deserializeAppError(message: unknown): AppError | null {
  if (typeof message !== 'string') return null;
  const at = message.lastIndexOf(WIRE_PREFIX);
  if (at < 0) return null;
  const code = message.slice(at + WIRE_PREFIX.length).trim();
  return isAppErrorCode(code) ? new AppError(code) : null;
}

// What: wraps one IPC handler so every failure leaves as a typed code.
// Why: a handler can throw anything; the page must never receive that text or a stack.
// Removed: raw "Error invoking remote method" text and internal diagnostics would reach the page.
import type { IpcMainInvokeEvent } from 'electron';
import {
  AppError,
  serializeAppError,
  toAppError,
  type AppErrorCode,
} from '../shared/errors.js';
import { logError } from './log.js';

export type IpcHandler = (event: IpcMainInvokeEvent, payload: unknown) => unknown | Promise<unknown>;
export type UnexpectedReporter = (channel: string, error: unknown) => void;

function reportUnexpected(channel: string, error: unknown): void {
  const detail = error instanceof Error ? error.message : 'unknown error';
  logError(`[chesspulse] ${channel} failed: ${detail}`);
}

/**
 * Registers nothing and imports no Electron runtime, so the contract is testable in plain Node.
 * An AppError is passed through; anything else is reduced to `fallback` and logged on this side.
 */
export function guardIpcHandler(
  channel: string,
  handler: IpcHandler,
  fallback: AppErrorCode = 'internal',
  report: UnexpectedReporter = reportUnexpected,
): (event: IpcMainInvokeEvent, payload: unknown) => Promise<unknown> {
  return async (event, payload) => {
    try {
      return await handler(event, payload);
    } catch (error) {
      if (!(error instanceof AppError)) report(channel, error);
      throw new Error(serializeAppError(toAppError(error, fallback)));
    }
  };
}

