// What: stores the explicit consent flag and answers the page on one channel.
// Why: the camera permission handler reads this flag, and the page cannot set it by any other path.
// Removed: revoking consent would not reach the process that grants the camera.
import { consentStateSchema } from '../shared/contracts.js';
import { registerInvokeChannel } from './ipc-registry.js';
import { grantsMediaPermission } from './permission.js';

let consentGranted = false;

export function currentConsent(): boolean {
  return consentGranted;
}

export interface ConsentHooks {
  /** Called after consent is withdrawn, so the process holding the camera can let go. */
  onRevoked?: () => void;
}

export interface ConsentOptions {
  appFileUrl: string;
  devOrigin?: string;
}

export function registerConsentHandler(options: ConsentOptions, hooks: ConsentHooks = {}): void {
  registerInvokeChannel('consentSet', (event, payload) => {
    const wasGranted = consentGranted;
    consentGranted = payload.granted;
    if (wasGranted && !consentGranted) {
      try {
        hooks.onRevoked?.();
      } catch {
        // The flag is already off; the page cannot re-open the camera through this path.
      }
    }
    return consentStateSchema.parse({
      granted: consentGranted,
      cameraAllowed: grantsMediaPermission({
        permission: 'media',
        requestingUrl: event.senderFrame?.url,
        appFileUrl: options.appFileUrl,
        devOrigin: options.devOrigin,
        consentGranted,
        isMainFrame: true,
        mediaTypes: ['video'],
      }),
    });
  });
}

// What: answers Paste screen validation requests over IPC using the main-process parser.
// Why: keeps PGN parsing and order enforcement in main so renderer and report builder never diverge.
// Removed: the Paste screen could not validate games or enforce chronological order.
import { pasteValidationSchema } from '../shared/contracts.js';
import { validatePasteBatch } from './analysis/paste.js';
import { registerInvokeChannel } from './ipc-registry.js';

export function registerPasteHandler(): void {
  registerInvokeChannel('pasteValidate', (_event, payload) =>
    pasteValidationSchema.parse(validatePasteBatch(payload.slots)),
  );
}

// What: exposes local report building, progress, and cancellation over IPC.
// Why: the engine and stored session files stay in main; the renderer receives only validated results.
// Removed: the Report screen could not request a real report, see progress, or stop one.
import {
  reportCancelResultSchema,
  reportProgressSchema,
  reportResultSchema,
} from '../shared/contracts.js';
import { EVENT_CHANNELS } from '../shared/channels.js';
import { AppError } from '../shared/errors.js';
import { registerInvokeChannel } from './ipc-registry.js';
import { buildReport } from './report.js';
import { withReportExclusion } from './report-lock.js';
import { defaultDataRoot } from './store.js';

interface ActiveBuild {
  controller: AbortController;
  /** Once true, the artifact commit has begun and a cancel request must not be acknowledged. */
  committing: boolean;
}

/** One active build per session. */
const activeBuilds = new Map<string, ActiveBuild>();

export function registerReportHandler(dataRoot: () => string = defaultDataRoot): void {
  registerInvokeChannel('reportBuild', async (event, payload) => {
    const { sessionId, pgns } = payload;
    if (activeBuilds.has(sessionId)) throw new AppError('session_busy');
    const build: ActiveBuild = { controller: new AbortController(), committing: false };
    activeBuilds.set(sessionId, build);
    try {
      // Shared exclusion also covers insight artifact reads; only one Stockfish build runs at once.
      const result = await withReportExclusion(() =>
        buildReport(dataRoot(), sessionId, pgns, undefined, {
          signal: build.controller.signal,
          onCommitStart: () => {
            build.committing = true;
          },
          onProgress: (progress) => {
            if (event.sender.isDestroyed()) return;
            const message = reportProgressSchema.safeParse({ sessionId, ...progress });
            if (message.success) event.sender.send(EVENT_CHANNELS.reportProgress, message.data);
          },
        }),
      );
      return reportResultSchema.parse(result);
    } finally {
      if (activeBuilds.get(sessionId) === build) activeBuilds.delete(sessionId);
    }
  });

  registerInvokeChannel('reportCancel', (_event, payload) => {
    const build = activeBuilds.get(payload.sessionId);
    if (!build) return reportCancelResultSchema.parse({ cancelled: false });
    // A commit already in progress is not cancellable; acknowledging it would lie about the artifact.
    if (build.committing) return reportCancelResultSchema.parse({ cancelled: false });
    build.controller.abort();
    return reportCancelResultSchema.parse({ cancelled: true });
  });
}

// What: serves optional AI readings from the stored report and original PGNs.
// Why: the renderer never supplies grounding statistics, and one session has at most one active call.
// Removed: a stale or forged renderer payload could reach a provider without cancellation or an audit id.
import { randomUUID } from 'node:crypto';
import { insightResultSchema } from '../shared/contracts.js';
import { AppError, toAppError } from '../shared/errors.js';
import { requestInsight } from './ai/service.js';
import { AiProviderError } from './ai/providers.js';
import { GroundingError } from './ai/grounding.js';
import { registerInvokeChannel } from './ipc-registry.js';
import { log, logError } from './log.js';
import { withReportExclusion } from './report-lock.js';
import { defaultDataRoot, readGames, readReport } from './store.js';

export function registerInsightHandler(dataRoot: () => string = defaultDataRoot, env: NodeJS.ProcessEnv = process.env): void {
  const active = new Map<string, AbortController>();

  registerInvokeChannel('insightRequest', async (_event, payload) => {
    if (active.has(payload.sessionId)) throw new AppError('session_busy');
    const requestId = randomUUID();
    const controller = new AbortController();
    active.set(payload.sessionId, controller);
    try {
      const artifacts = await readArtifacts(dataRoot(), payload.sessionId, controller.signal).catch(
        (error: unknown) => {
          throw toAppError(error, 'report_failed');
        },
      );
      // Provider and grounding failures carry their own meaning; anything else is a report fault.
      const result = insightResultSchema.parse(
        await requestInsight(payload, artifacts.report, artifacts.pgns, env, { signal: controller.signal }).catch(
          (error: unknown) => {
            if (error instanceof AppError) throw error;
            if (error instanceof AiProviderError) throw new AppError(error.code, { cause: error });
            if (error instanceof GroundingError) throw new AppError('ai_ungrounded', { cause: error });
            throw toAppError(error, 'report_failed');
          },
        ),
      );
      log(`[chesspulse] AI reading ${requestId} ${result.disabled ? 'disabled' : 'ready'}`);
      return result;
    } catch (error) {
      logError(`[chesspulse] AI reading ${requestId} failed: ${error instanceof Error ? error.message : 'unknown error'}`);
      throw error;
    } finally {
      if (active.get(payload.sessionId) === controller) active.delete(payload.sessionId);
    }
  });

  registerInvokeChannel('insightCancel', (_event, payload) => {
    const controller = active.get(payload.sessionId);
    controller?.abort();
    return { cancelled: controller !== undefined };
  });
}

function readArtifacts(
  root: string,
  sessionId: string,
  signal: AbortSignal,
): Promise<{ report: Awaited<ReturnType<typeof readReport>>; pgns: string[] }> {
  return withReportExclusion(async () => ({
    report: await readReport(root, sessionId),
    pgns: await readGames(root, sessionId),
  }), signal);
}

