      };
      const stopOwnedWorker = (): void => {
        if (owned) void current.terminate().catch(() => undefined);
      };
      const onError = (): void => {
        dropWorker();
        finish({ fen, depth, evalFailed: true, reason: 'crash' });
        stopOwnedWorker();
      };
      const onExit = (): void => {
        dropWorker();
        finish({ fen, depth, evalFailed: true, reason: 'crash' });
      };
      const onAbort = (): void => {
        dropWorker();
        finish(cancelled(fen));
        // A borrowed worker is the caller's to stop; only terminate what the engine created.
        stopOwnedWorker();
      };
      const onMessage = (message: unknown): void => {
        if (!isWorkerEval(message) || message.id !== id) return;
        if (message.failed === true || (message.scoreCp === undefined && message.mate === undefined)) {
          finish({ fen, depth, evalFailed: true, reason: 'engine', bestmove: message.bestmove });
          return;
        }
        finish({
          fen,
          depth,
          evalFailed: false,
          scoreCp: message.scoreCp,
          mate: message.mate,
          bestmove: message.bestmove,
        });
      };
      timer = setTimeout(() => {
        dropWorker();
        finish({ fen, depth, evalFailed: true, reason: 'timeout' });
        stopOwnedWorker();
      }, timeoutMs);
      current.on('message', onMessage);
      current.on('error', onError);
      current.on('exit', onExit);
      signal?.addEventListener('abort', onAbort, { once: true });
      if (signal?.aborted) {
        onAbort();
        return;
      }
      try {
        current.postMessage({ type: 'eval', id, fen, depth });
      } catch {
        // A postMessage throw means this attempt failed; dispose an owned worker before retrying.
        onError();
      }
    });
  }

  async function close(): Promise<void> {
    await queue;
    if (!ownsWorker || !worker) return;
    const current = worker;
    worker = undefined;
    ownsWorker = false;
    await current.terminate();
  }

  return { evaluate, close, depth };
}

function isWorkerEval(message: unknown): message is WorkerEval {
  return typeof message === 'object' && message !== null && (message as WorkerEval).type === 'eval';
}

function gapClause(gaps: readonly { afterIndex: number; beforeIndex: number; durationUs: number }[]): string | undefined {
  const gap = gaps.reduce<(typeof gaps)[number] | undefined>((best, current) => {
    if (!best || current.durationUs > best.durationUs) return current;
    return best;
  }, undefined);
  if (!gap) return undefined;
  const minutes = Math.round(gap.durationUs / 60_000_000);
  const seconds = Math.max(1, Math.round(gap.durationUs / 1_000_000));
  const waited =
    minutes >= 1
      ? `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`
      : `${seconds} ${seconds === 1 ? 'second' : 'seconds'}`;
  return `Between games ${gap.afterIndex + 1} and ${gap.beforeIndex + 1} you waited ${waited}.`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === __filename) {
  main(process.argv).then(
    (code) => process.exit(code),
    (error: unknown) => {
      const message = error instanceof Error ? error.message : 'The report could not be built.';
      process.stderr.write(`${message}\n`);
      process.exit(1);
    },
  );
}
