function sixtyPositions(): string[] {
  const chess = new Chess();
  const fens: string[] = [];
  while (fens.length < 60) {
    if (chess.isGameOver()) chess.reset();
    const next = chess.moves()[0];
    if (!next) {
      chess.reset();
      continue;
    }
    chess.move(next);
    fens.push(chess.fen());
  }
  return fens;
}

